    for (let i = 0; i < FRAME; i++) energy += samples[off + i] ** 2
    if (energy / FRAME < 1e-5) continue // 静音帧跳过
    let bestLag = -1, bestVal = 0
    for (let lag = MIN_LAG; lag <= MAX_LAG; lag++) {
